        "source": "Original problem in the style of Khan Academy College Algebra (Exponents and radicals), CC BY-NC-SA 4.0",
        "sourceUrl": "https://www.khanacademy.org/math/college-algebra/xa5dd2923c88e7aa8:exponents-and-radicals"
