        "source": "Original problem in the style of Khan Academy College Algebra (Rational expressions and equations), CC BY-NC-SA 4.0",
        "sourceUrl": "https://www.khanacademy.org/math/college-algebra/xa5dd2923c88e7aa8:rational-expressions-and-equations"
