    "samples": [
      {
        "topic": "Operations with negative numbers (7.NS)",
        "problem": "The temperature at noon was $4^\\circ\\text{C}$. By midnight it had dropped $11^\\circ\\text{C}$. What was the temperature at midnight?",
        "answer": "$4 + (-11) = -7^\\circ\\text{C}$.",
        "source": "Original problem in the style of Khan Academy 7th grade math (Negative numbers: addition and subtraction); CC BY-NC-SA",
        "sourceUrl": "https://www.khanacademy.org/math/cc-seventh-grade-math/cc-7th-negative-numbers-add-and-subtract"
      },
      {
        "topic": "Multiplying & dividing rational numbers (7.NS)",
        "problem": "Evaluate $(-3) \\times (-4) \\div (-2)$.",
        "answer": "$(-3)\\times(-4)=12$, then $12 \\div (-2) = -6$.",
        "source": "Original problem in the style of Khan Academy 7th grade math (Negative numbers: multiplication and division); CC BY-NC-SA",
        "sourceUrl": "https://www.khanacademy.org/math/cc-seventh-grade-math/cc-7th-negative-numbers-multiply-and-divide"
      },
      {
        "topic": "Percents: tax, tip, and discount (7.RP / fractions, decimals, percentages)",
        "problem": "A jacket is marked $\\$60$. It is on sale for $25\\%$ off, and then $8\\%$ sales tax is added to the sale price. What is the final price?",
        "answer": "Sale price: $60 \\times (1-0.25) = \\$45$. With tax: $45 \\times 1.08 = \\$48.60$.",
        "source": "Original problem in the style of Khan Academy 7th grade math (Fractions, decimals, & percentages); CC BY-NC-SA",
        "sourceUrl": "https://www.khanacademy.org/math/cc-seventh-grade-math/cc-7th-fractions-decimals"
      },
      {
        "topic": "Proportional relationships & constant of proportionality (7.RP)",
        "problem": "A car travels at a constant speed and covers $150$ miles in $3$ hours. Write an equation relating distance $d$ to time $t$, and find the distance traveled in $5$ hours.",
        "answer": "Constant of proportionality (speed) $= 150/3 = 50$ mph, so $d = 50t$. In $5$ hours: $d = 50(5) = 250$ miles.",
        "source": "Original problem in the style of Illustrative Mathematics Grade 7, 7.RP (Ratios and Proportional Relationships); CC BY-NC-SA 4.0",
        "sourceUrl": "https://tasks.illustrativemathematics.org/content-standards/7/RP"
      },
      {
        "topic": "Two-step equations (7.EE)",
        "problem": "Solve for $x$: $3x - 7 = 14$.",
        "answer": "$3x = 21$, so $x = 7$.",
        "source": "Original problem in the style of Khan Academy 7th grade math (Expressions, equations, & inequalities); CC BY-NC-SA",
        "sourceUrl": "https://www.khanacademy.org/math/cc-seventh-grade-math/cc-7th-variables-expressions"
      },
      {
        "topic": "Two-step inequalities (7.EE)",
        "problem": "Solve and graph: $-2x + 5 \\le 11$.",
        "answer": "$-2x \\le 6$; dividing by $-2$ flips the inequality: $x \\ge -3$.",
        "source": "Original problem in the style of Illustrative Mathematics Grade 7, 7.EE (Expressions and Equations); CC BY-NC-SA 4.0",
        "sourceUrl": "https://tasks.illustrativemathematics.org/content-standards/7/EE"
      },
      {
        "topic": "Area & circumference of circles (7.G)",
        "problem": "A circular garden has a radius of $7$ m. Using $\\pi \\approx \\frac{22}{7}$, find its circumference and area.",
        "answer": "Circumference $= 2\\pi r = 2 \\times \\tfrac{22}{7} \\times 7 = 44$ m. Area $= \\pi r^2 = \\tfrac{22}{7} \\times 7^2 = 154$ m$^2$.",
        "source": "Original problem in the style of Khan Academy 7th grade math (Geometry); CC BY-NC-SA",
        "sourceUrl": "https://www.khanacademy.org/math/cc-seventh-grade-math/cc-7th-geometry"
      },
      {
        "topic": "Simple probability (7.SP)",
        "problem": "A bag contains $5$ red, $3$ blue, and $2$ green marbles. If one marble is drawn at random, what is the probability it is NOT blue?",
        "answer": "Total $=10$; non-blue $=7$, so $P(\\text{not blue}) = \\tfrac{7}{10} = 0.7$.",
        "source": "Original problem in the style of Khan Academy 7th grade math (Statistics and probability); CC BY-NC-SA",
        "sourceUrl": "https://www.khanacademy.org/math/cc-seventh-grade-math/cc-7th-probability-statistics"
      }
    ],
