    "samples": [
      {
        "topic": "Aquatic biomes — freshwater vs. marine, salinity",
        "problem": "Aquatic biomes are classified largely by salinity. List the two broad categories of aquatic biome and give two example ecosystems for each. Where do estuaries fit, and what makes their salinity unusual?",
        "answer": "The two categories are freshwater biomes (e.g., lakes/ponds and rivers/streams; wetlands also included) and marine biomes (e.g., the open ocean and coral reefs). Estuaries are transitional zones where rivers meet the sea, so they are brackish — salinity is intermediate and fluctuates with tides and freshwater inflow, ranging between freshwater (~0 ppt) and seawater (~35 ppt).",
        "source": "OpenStax Biology 2e, Section 44.4 Aquatic Biomes (CC BY 4.0)",
        "sourceUrl": "https://openstax.org/books/biology-2e/pages/44-4-aquatic-biomes"
      },
      {
        "topic": "Light zones in aquatic systems",
        "problem": "In a deep lake or ocean, biologists distinguish the photic zone from the aphotic zone. Define each zone, give the approximate depth boundary, and explain why photosynthetic organisms are restricted to the photic zone.",
        "answer": "The photic (or euphotic) zone is the upper layer where light penetrates, roughly the top $200\\ \\text{m}$; the aphotic zone lies below it where light cannot penetrate. Photosynthetic organisms (phytoplankton, algae, aquatic plants) are confined to the photic zone because photosynthesis requires light, which is absorbed and scattered by water and dissolved/suspended material with increasing depth.",
        "source": "OpenStax Biology 2e, Section 44.4 Aquatic Biomes (CC BY 4.0)",
        "sourceUrl": "https://openstax.org/books/biology-2e/pages/44-4-aquatic-biomes"
      },
      {
        "topic": "Trophic levels and energy transfer (10% rule)",
        "problem": "Energy transfer between trophic levels is inefficient — on average only about 10% of the energy at one level reaches the next. If the primary producers in a pond fix $20{,}000\\ \\text{kcal/m}^2/\\text{yr}$, estimate the energy available to (a) the primary consumers and (b) the secondary consumers using the 10% rule. Why is so much energy lost?",
        "answer": "(a) Primary consumers receive about $10\\%$ of $20{,}000 = 2{,}000\\ \\text{kcal/m}^2/\\text{yr}$. (b) Secondary consumers receive about $10\\%$ of $2{,}000 = 200\\ \\text{kcal/m}^2/\\text{yr}$. Energy is lost mainly as heat through cellular respiration, and additional energy is never consumed or is lost in egestion (waste), so only a fraction is stored as new biomass available to the next level.",
        "source": "Modeled on OpenStax Biology 2e, Section 46.1/46.2 Ecology of Ecosystems & energy flow (CC BY 4.0)",
        "sourceUrl": "https://openstax.org/books/biology-2e/pages/46-1-ecology-of-ecosystems"
      },
      {
        "topic": "Food chains vs. food webs",
        "problem": "Explain the difference between a food chain and a food web in an aquatic ecosystem. Using phytoplankton, zooplankton, small fish, and a heron, write one possible food chain and identify the trophic level of each organism.",
        "answer": "A food chain is a single linear sequence showing one path of energy/nutrient flow, while a food web is a network of many interconnected food chains that more realistically represents who eats whom. Example chain: phytoplankton (producer, 1st trophic level) → zooplankton (primary consumer, 2nd) → small fish (secondary consumer, 3rd) → heron (tertiary consumer, 4th).",
        "source": "OpenStax Biology 2e, Section 46.1 Ecology of Ecosystems (CC BY 4.0)",
        "sourceUrl": "https://openstax.org/books/biology-2e/pages/46-1-ecology-of-ecosystems"
      },
      {
        "topic": "Dissolved oxygen and water temperature",
        "problem": "Cold water holds more dissolved oxygen than warm water. Explain how thermal pollution from a power plant discharging warm water into a river could harm fish, and name one adaptation or behavior fish use to cope with low dissolved oxygen.",
        "answer": "Warming the water lowers its dissolved-oxygen capacity while simultaneously raising fish metabolic rates (and thus their oxygen demand). The combination can drop dissolved oxygen below what fish need, causing stress, reduced growth, or kills. Fish may cope by moving to cooler, more oxygenated water, increasing gill ventilation, or gulping air at the surface (aquatic surface respiration).",
        "source": "Original problem in the style of NOAA Estuary Education water-quality lessons",
        "sourceUrl": "https://coast.noaa.gov/estuaries/curriculum/"
      },
      {
        "topic": "Watersheds and nonpoint-source pollution",
        "problem": "Define a watershed. In a watershed model, students add fertilizer to farmland and oil to a parking lot, then simulate rainfall. Predict what happens to these pollutants and explain why they are called 'nonpoint-source' pollution.",
        "answer": "A watershed is all the land area that drains to a common body of water (stream, lake, bay, or ocean). During simulated rain, runoff carries the fertilizer and oil downhill across the land and into the receiving water body. They are 'nonpoint-source' because they do not come from a single identifiable pipe or outlet — they wash off broad areas of the landscape, making them hard to trace and regulate.",
        "source": "Modeled on NOAA Estuary Education 'Watershed in a Box' / watershed model activity (public domain)",
        "sourceUrl": "https://coast.noaa.gov/estuaries/curriculum/watershed-in-a-box.html"
      },
      {
        "topic": "Biogeochemical cycles — the nitrogen cycle",
        "problem": "Nutrients such as nitrogen cycle through aquatic ecosystems. Name the process by which certain bacteria convert atmospheric $N_2$ into a usable form, and briefly describe how excess nitrogen entering a lake can lead to eutrophication.",
        "answer": "Nitrogen fixation, carried out by nitrogen-fixing bacteria (and cyanobacteria), converts atmospheric $N_2$ into ammonia/ammonium that organisms can use. Excess nitrogen (from fertilizer or wastewater) acts as a nutrient that fuels rapid algal growth (an algal bloom); when the algae die, decomposers consume oxygen as they break them down, depleting dissolved oxygen and causing fish kills — this nutrient-driven decline is eutrophication.",
        "source": "Modeled on CK-12 Biology FlexBook biogeochemical cycles & Khan Academy biogeochemical cycles (CC BY-NC)",
        "sourceUrl": "https://www.khanacademy.org/science/high-school-biology/hs-ecology/hs-biogeochemical-cycles/a/hs-biogeochemical-cycles-review"
      },
      {
        "topic": "Population ecology — carrying capacity",
        "problem": "A fish population in a reservoir grows quickly at first, then levels off near $K = 5{,}000$ individuals. Identify this growth pattern, define carrying capacity ($K$), and give two density-dependent factors that could limit the population as it approaches $K$.",
        "answer": "This is logistic growth (an S-shaped curve). Carrying capacity $K$ is the maximum population size the environment can sustain given available resources. Density-dependent limiting factors include competition for food/space, predation, and the spread of disease/parasites — their effect intensifies as population density rises toward $K$.",
        "source": "Modeled on Khan Academy High School Biology — Population ecology (CC BY-NC-SA)",
        "sourceUrl": "https://www.khanacademy.org/science/high-school-biology/hs-ecology/hs-population-ecology/a/population-size-density-and-distribution"
      }
    ],
