    "samples": [
      {
        "topic": "Geography Basics — coordinates",
        "problem": "A location is described as lying at $23.5^\\circ$ N latitude. What is the name of this important line of latitude, and what is geographically special about it?",
        "answer": "It is the Tropic of Cancer. It marks the northernmost latitude where the Sun can appear directly overhead (at the June solstice), due to Earth's $23.5^\\circ$ axial tilt.",
        "source": "CK-12 / K12 LibreTexts — Geography Basics",
        "sourceUrl": "https://k12.libretexts.org/Bookshelves/Geography/01:_Physical_Patterns_and_Processes_(15_days)/1.01:_Geography_Basics_(8_Days)"
      },
      {
        "topic": "Maps and time zones",
        "problem": "Earth is divided into 24 time zones across $360^\\circ$ of longitude. How many degrees of longitude does each standard time zone span? Show the calculation.",
        "answer": "$360^\\circ \\div 24 = 15^\\circ$ of longitude per time zone.",
        "source": "CK-12 / K12 LibreTexts — Geography Basics",
        "sourceUrl": "https://k12.libretexts.org/Bookshelves/Geography/01:_Physical_Patterns_and_Processes_(15_days)/1.01:_Geography_Basics_(8_Days)"
      },
      {
        "topic": "Types of regions",
        "problem": "Classify each as a formal, functional, or vernacular (perceptual) region: (a) the state of Texas, (b) the delivery area of a local pizza shop, (c) 'the Sun Belt.'",
        "answer": "(a) Formal region (defined political boundary); (b) Functional region (organized around a node/service); (c) Vernacular/perceptual region (defined by people's informal perceptions).",
        "source": "CK-12 / K12 LibreTexts — Geography Basics",
        "sourceUrl": "https://k12.libretexts.org/Bookshelves/Geography/01:_Physical_Patterns_and_Processes_(15_days)/1.01:_Geography_Basics_(8_Days)"
      },
      {
        "topic": "Geospatial tools",
        "problem": "Match the tool to its function: GPS, GIS, remote sensing. (1) Layers spatial data to analyze relationships on a digital map; (2) Uses satellite signals to determine exact latitude/longitude; (3) Collects Earth-surface data from aerial photos and satellite imagery.",
        "answer": "GPS = (2); GIS = (1); Remote sensing = (3).",
        "source": "CK-12 / K12 LibreTexts — Geography Basics",
        "sourceUrl": "https://k12.libretexts.org/Bookshelves/Geography/01:_Physical_Patterns_and_Processes_(15_days)/1.01:_Geography_Basics_(8_Days)"
      },
      {
        "topic": "Physical vs. human geography",
        "problem": "Decide whether each topic belongs to physical geography or human geography: (a) the course of the Amazon River, (b) the spread of the Spanish language in Latin America, (c) mountain-building along plate boundaries, (d) the growth of megacities.",
        "answer": "(a) Physical; (b) Human; (c) Physical; (d) Human.",
        "source": "CK-12 / K12 LibreTexts — Geography Basics",
        "sourceUrl": "https://k12.libretexts.org/Bookshelves/Geography/01:_Physical_Patterns_and_Processes_(15_days)/1.01:_Geography_Basics_(8_Days)"
      },
      {
        "topic": "Population & migration",
        "problem": "Sort these into 'push' and 'pull' migration factors: drought and crop failure; abundant job opportunities; political persecution; better schools and healthcare.",
        "answer": "Push factors (drive people away): drought/crop failure, political persecution. Pull factors (attract people): abundant job opportunities, better schools and healthcare.",
        "source": "CK-12 / K12 LibreTexts — Human Geographic Systems (Population and Culture)",
        "sourceUrl": "https://k12.libretexts.org/Bookshelves/Geography/02:_Human_Geographic_Systems_(15_days)"
      },
      {
        "topic": "Economic activity classification",
        "problem": "Identify the economic sector (primary, secondary, tertiary) for each job: (a) wheat farmer, (b) auto-assembly worker, (c) elementary school teacher.",
        "answer": "(a) Primary (extracting/producing raw materials); (b) Secondary (manufacturing/processing); (c) Tertiary (services).",
        "source": "Original prompt in the style of CK-12 / K12 LibreTexts — Human Geographic Systems",
        "sourceUrl": "https://k12.libretexts.org/Bookshelves/Geography/02:_Human_Geographic_Systems_(15_days)"
      },
      {
        "topic": "Regional geography — Latin America",
        "problem": "Name the major mountain range that runs along the western edge of South America, and explain one way it influences the continent's climate and settlement patterns.",
        "answer": "The Andes. By blocking moisture-bearing winds it creates a rain shadow (contributing to the dry Atacama Desert) and its high elevations create cooler 'altitude zones' where many people live despite the tropical latitude.",
        "source": "CK-12 / K12 LibreTexts — Latin America (South America: Physical Geography)",
        "sourceUrl": "https://k12.libretexts.org/Bookshelves/Geography/04:_Latin_America_(10_days)/4.05:_South_America-_Physical_Geography_(1_Day)"
      }
    ]
