        "problem": "Which theory is most likely to examine the social world at a micro level? (A) Structural functionalism (B) Conflict theory (C) Positivism (D) Symbolic interactionism",
        "answer": "D — Symbolic interactionism (it focuses on small-scale, face-to-face interaction).",
        "source": "OpenStax, Introduction to Sociology 3e, Ch. 1 Section Quiz (CC BY-NC-SA 4.0)",
