    "samples": [
      {
        "topic": "Kinematics (1D motion)",
        "problem": "A car starts from rest and accelerates uniformly at $3.0\\ \\text{m/s}^2$ for $5.0\\ \\text{s}$. How far does it travel during this time?",
        "answer": "Using $d = v_0 t + \\tfrac{1}{2} a t^2 = 0 + \\tfrac{1}{2}(3.0)(5.0)^2 = 37.5\\ \\text{m}$.",
        "source": "Original problem in the style of OpenStax College Physics, Ch. 2 (Kinematics), CC BY",
        "sourceUrl": "https://openstax.org/books/college-physics-2e/pages/2-introduction-to-one-dimensional-kinematics"
      },
      {
        "topic": "Newton's second law (forces)",
        "problem": "A net force of $20\\ \\text{N}$ acts on a $4.0\\ \\text{kg}$ object. What is the object's acceleration?",
        "answer": "From $F = ma$, $a = F/m = 20/4.0 = 5.0\\ \\text{m/s}^2$, in the direction of the net force.",
        "source": "Original problem in the style of OpenStax College Physics, Ch. 4 (Dynamics: Newton's Laws of Motion), CC BY",
        "sourceUrl": "https://openstax.org/books/college-physics-2e/pages/4-3-newtons-second-law-of-motion-concept-of-a-system"
      },
      {
        "topic": "Projectile motion (2D)",
        "problem": "A ball is thrown horizontally at $15\\ \\text{m/s}$ from a cliff $20\\ \\text{m}$ high. How long is it in the air, and how far from the base does it land? (Take $g = 9.8\\ \\text{m/s}^2$.)",
        "answer": "Time: $20 = \\tfrac{1}{2}(9.8)t^2 \\Rightarrow t \\approx 2.0\\ \\text{s}$. Range: $x = (15)(2.0) \\approx 30\\ \\text{m}$.",
        "source": "Original problem in the style of OpenStax College Physics, Ch. 3 (Two-Dimensional Kinematics), CC BY",
        "sourceUrl": "https://openstax.org/books/college-physics-2e/pages/3-4-projectile-motion"
      },
      {
        "topic": "Work and energy",
        "problem": "How much work is done by a $50\\ \\text{N}$ force pushing a box $4.0\\ \\text{m}$ across a floor in the direction of the force?",
        "answer": "$W = Fd\\cos\\theta = (50)(4.0)\\cos 0^\\circ = 200\\ \\text{J}$.",
        "source": "Original problem in the style of CK-12 Physics FlexBook 2.0, Work and Energy, CC BY-NC",
        "sourceUrl": "https://flexbooks.ck12.org/cbook/ck-12-physics-flexbook-2.0/section/7.1/primary/lesson/work-phys/"
      },
      {
        "topic": "Conservation of energy",
        "problem": "A $2.0\\ \\text{kg}$ rock is dropped from a height of $10\\ \\text{m}$. Using energy conservation, find its speed just before it hits the ground. (Take $g = 9.8\\ \\text{m/s}^2$.)",
        "answer": "$mgh = \\tfrac{1}{2}mv^2 \\Rightarrow v = \\sqrt{2gh} = \\sqrt{2(9.8)(10)} \\approx 14\\ \\text{m/s}$.",
        "source": "Original problem in the style of OpenStax College Physics, Ch. 7 (Work, Energy, and Energy Resources), CC BY",
        "sourceUrl": "https://openstax.org/books/college-physics-2e/pages/7-introduction-to-work-energy-and-energy-resources"
      },
      {
        "topic": "Momentum and impulse",
        "problem": "A $0.50\\ \\text{kg}$ ball moving at $4.0\\ \\text{m/s}$ is brought to rest by a wall. What is the magnitude of the impulse exerted on the ball?",
        "answer": "Impulse equals change in momentum: $J = \\Delta p = m\\,\\Delta v = (0.50)(0 - 4.0) = -2.0\\ \\text{kg·m/s}$, so magnitude $2.0\\ \\text{N·s}$.",
        "source": "Original problem in the style of Khan Academy high school physics (Force pairs and momentum), CC BY-NC-SA",
        "sourceUrl": "https://www.khanacademy.org/science/hs-physics-tx/x52b5e54e482d5bbe:force-pairs-and-momentum/x52b5e54e482d5bbe:impulse/v/impulse"
      },
      {
        "topic": "Gravitation",
        "problem": "Using Newton's law of universal gravitation, by what factor does the gravitational force between two masses change if the distance between them is doubled?",
        "answer": "Since $F \\propto 1/r^2$, doubling $r$ gives $F' = F/2^2 = F/4$. The force drops to one-quarter.",
        "source": "Original problem in the style of CK-12 Physics FlexBook 2.0, Circular Motion and Gravity, CC BY-NC",
        "sourceUrl": "https://flexbooks.ck12.org/cbook/ck-12-physics-flexbook-2.0/section/5.4/primary/lesson/orbital-motion-phys/"
      },
      {
        "topic": "Waves",
        "problem": "A wave has a frequency of $250\\ \\text{Hz}$ and a wavelength of $1.4\\ \\text{m}$. What is its speed?",
        "answer": "$v = f\\lambda = (250)(1.4) = 350\\ \\text{m/s}$.",
        "source": "Original problem in the style of Khan Academy high school physics (Waves), CC BY-NC-SA",
        "sourceUrl": "https://www.khanacademy.org/science/hs-physics-tx/x52b5e54e482d5bbe:waves/x52b5e54e482d5bbe:wave-properties/v/introduction-to-waves"
      }
    ]
