    "samples": [
      {
        "topic": "Historical thinking / sources",
        "problem": "What is an example of a primary source?",
        "answer": "A diary entry written by a person who lived in the period under discussion.",
        "source": "OpenStax, World History Volume 1, Ch. 1 Review Questions (CC BY-NC-SA 4.0)",
        "sourceUrl": "https://openstax.org/books/world-history-volume-1/pages/1-review-questions"
      },
      {
        "topic": "Historiography",
        "problem": "What interpretation of history assumes that history can be viewed primarily through the lives and choices of leaders?",
        "answer": "The 'great man' theory of history.",
        "source": "OpenStax, World History Volume 1, Ch. 1 Review Questions (CC BY-NC-SA 4.0)",
        "sourceUrl": "https://openstax.org/books/world-history-volume-1/pages/1-review-questions"
      },
      {
        "topic": "Foundations of history (East Asian historiography)",
        "problem": "Whom do the Chinese traditionally regard as the 'Father of History'?",
        "answer": "Sima Qian (author of the Records of the Grand Historian).",
        "source": "OpenStax, World History Volume 1, Ch. 1 Review Questions (CC BY-NC-SA 4.0)",
        "sourceUrl": "https://openstax.org/books/world-history-volume-1/pages/1-review-questions"
      },
      {
        "topic": "Industrialization / Second Industrial Revolution",
        "problem": "Which invention enabled nineteenth-century manufacturers to power machinery in locations where steam engines were too big to be used?",
        "answer": "The internal combustion engine.",
        "source": "OpenStax, World History Volume 2, Ch. 9 Review Questions (CC BY-NC-SA 4.0)",
        "sourceUrl": "https://openstax.org/books/world-history-volume-2/pages/9-review-questions"
      },
      {
        "topic": "Imperialism / technology of empire",
        "problem": "Which industrial innovation aided European colonization in the second half of the nineteenth century?",
        "answer": "The Maxim gun (the first self-powered machine gun).",
        "source": "OpenStax, World History Volume 2, Ch. 9 Review Questions (CC BY-NC-SA 4.0)",
        "sourceUrl": "https://openstax.org/books/world-history-volume-2/pages/9-review-questions"
      },
      {
        "topic": "State-building, c. 1200–1450 (AP-style comparison)",
        "problem": "How was the process of state formation similar to and different from one another in various regions of the world from c. $1200$ to $1450$ CE? Support your answer with specific examples (e.g., Song China, the Delhi Sultanate, Mali, and the Aztec and Inca states).",
        "answer": "Sample response: Many states centralized power by tying political authority to religion and bureaucracy — Song China used a Confucian civil-service exam meritocracy, the Delhi Sultanate and Mali leaders used Islam to legitimize rule, and the Inca used the cult of the Sapa Inca. They differed in administration: China and the Inca built large salaried/labor-tribute bureaucracies, while Mali and the Delhi Sultanate relied more on tribute from semi-autonomous regions and personal/military loyalty. (Style of the WHP-AP Unit 1 framing question.)",
        "source": "In the style of Khan Academy / OER Project World History Project AP, Unit 1: The Global Tapestry (CC BY-NC-SA)",
        "sourceUrl": "https://www.khanacademy.org/humanities/world-history-project-ap/xb41992e0ff5e0f09:unit-1-the-global-tapestry"
      },
      {
        "topic": "Causation — Neolithic Revolution",
        "problem": "Explain how the shift from foraging to settled agriculture during the Neolithic Revolution led to the rise of the early river-valley civilizations. Identify at least two consequences.",
        "answer": "Sample response: Reliable farming surpluses (in valleys such as the Tigris-Euphrates, Nile, Indus, and Huang He) let populations grow and settle permanently. Surplus food supported specialization of labor, so not everyone farmed — enabling artisans, priests, and rulers — which in turn produced social hierarchies, organized religion, writing/record-keeping, and centralized states. (Style of CK-12 World History Studies, Neolithic Revolution lesson.)",
        "source": "In the style of CK-12 World History Studies (EPISD FlexBook), §1.4 The Neolithic Revolution and Rise of River Valley Civilizations (CC BY-NC)",
        "sourceUrl": "https://flexbooks.ck12.org/user:zxbpc2rzcziwmthaz21hawwuy29t/cbook/world-history-studies_episd/section/1.4/"
      },
      {
        "topic": "Enlightenment & revolutions",
        "problem": "How did Enlightenment ideas about natural rights, the social contract, and separation of powers influence the political revolutions of the late eighteenth and early nineteenth centuries? Give one specific example.",
        "answer": "Sample response: Thinkers like Locke (natural rights, consent of the governed), Rousseau (social contract), and Montesquieu (separation of powers) provided the intellectual justification for challenging absolute monarchy. For example, the American Declaration of Independence echoes Locke's 'life, liberty, and the pursuit of happiness,' and the French Declaration of the Rights of Man asserts natural rights and popular sovereignty against the absolutist Old Regime. (Style of CK-12 World History Studies, Absolutism and Enlightenment lesson.)",
        "source": "In the style of CK-12 World History Studies (EPISD FlexBook), §6.4 Absolutism and Enlightenment (CC BY-NC)",
        "sourceUrl": "https://flexbooks.ck12.org/user:zxbpc2rzcziwmthaz21hawwuy29t/cbook/world-history-studies_episd/section/6.4/primary/lesson/absolutism-and-enlightenment/"
      }
    ],
