        "problem": "Chlorine has two stable isotopes: chlorine-35 ($34.969\\ \\text{amu}$, $75.77\\%$ abundance) and chlorine-37 ($36.966\\ \\text{amu}$, $24.23\\%$ abundance). Calculate the average atomic mass of chlorine.",
        "answer": "$(0.7577)(34.969) + (0.2423)(36.966) \\approx 35.45\\ \\text{amu}$, which matches the periodic-table value for Cl.",
        "source": "Original problem in the style of Khan Academy 'Average atomic mass' (HS Chemistry TX TEKS), CC BY-NC-SA",
