        "answer": "By Boyle's law, $P_1V_1 = P_2V_2 \\Rightarrow P_2 = \\dfrac{(1.00)(2.00)}{1.00} = 2.00\\ \\text{atm}$.",
        "source": "Original problem in the style of CK-12 Chemistry 'The Behavior of Gases', CC BY-NC",
